{"source": "def investigate(context, acquire):
    receipts = acquire("history")
    actions = context.get("actions", [])
    goal = context.get("goal")

    def sim_actions(acts, pm, cm, tr):
        committed = {}
        pending = {"main": None, "other": None}
        main_changes = 0
        main_total = 0
        other_total = 0

        def do_put(conn, key, value):
            nonlocal main_changes, main_total, other_total
            existed = key in committed
            if pm == "ignore":
                if existed:
                    changed = 0
                    inserted = False
                else:
                    committed[key] = value
                    changed = 1
                    inserted = True
            elif pm == "replace":
                committed[key] = value
                changed = 1
                inserted = True
            else:
                committed[key] = value
                changed = 1
                inserted = not existed
            trig = 1 if (tr and inserted) else 0
            if cm == "changes":
                if conn == "main":
                    main_changes = changed
            elif cm == "total_main":
                if conn == "main":
                    main_total += changed + trig
                else:
                    other_total += changed + trig
            else:
                if conn == "main":
                    main_total += changed + trig
                else:
                    other_total += changed + trig

        def do_update(conn, key, value):
            nonlocal main_changes, main_total, other_total
            if key in committed:
                committed[key] = value
                changed = 1
            else:
                changed = 0
            if cm == "changes":
                if conn == "main":
                    main_changes = changed
            elif cm == "total_main":
                if conn == "main":
                    main_total += changed
                else:
                    other_total += changed
            else:
                if conn == "main":
                    main_total += changed
                else:
                    other_total += changed

        def do_delete(conn, key):
            nonlocal main_changes, main_total, other_total
            if key in committed:
                del committed[key]
                changed = 1
            else:
                changed = 0
            if cm == "changes":
                if conn == "main":
                    main_changes = changed
            elif cm == "total_main":
                if conn == "main":
                    main_total += changed
                else:
                    other_total += changed
            else:
                if conn == "main":
                    main_total += changed
                else:
                    other_total += changed

        for act in acts:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                pending[conn] = []
            elif op == "commit":
                if pending[conn] is not None:
                    for (o, k, v) in pending[conn]:
                        if o == "put":
                            do_put(conn, k, v)
                        elif o == "update":
                            do_update(conn, k, v)
                        elif o == "delete":
                            do_delete(conn, k)
                    pending[conn] = None
            elif op == "rollback":
                pending[conn] = None
            elif op in ("put", "update", "delete"):
                if pending[conn] is not None:
                    pending[conn].append((op, act.get("key"), act.get("value")))
                else:
                    if op == "put":
                        do_put(conn, act.get("key"), act.get("value"))
                    elif op == "update":
                        do_update(conn, act.get("key"), act.get("value"))
                    elif op == "delete":
                        do_delete(conn, act.get("key"))

        if cm == "changes":
            channel = main_changes
        elif cm == "total_main":
            channel = main_total
        else:
            channel = main_total + other_total
        return channel, len(committed), sum(committed.values())

    put_modes = ["ignore", "replace", "upsert"]
    channel_modes = ["changes", "total_main", "total_both"]
    triggers = [False, True]

    consistent = []
    for pm in put_modes:
        for cm in channel_modes:
            for tr in triggers:
                ok = True
                for r in receipts:
                    ra = r.get("actions", [])
                    obs = r.get("observed", {})
                    ch, cnt, sm = sim_actions(ra, pm, cm, tr)
                    if ch != obs.get("channel") or cnt != obs.get("committed_count") or sm != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    consistent.append((pm, cm, tr))

    if not consistent:
        return {"value": None, "unresolved": True}

    results = set()
    for (pm, cm, tr) in consistent:
        ch, cnt, sm = sim_actions(actions, pm, cm, tr)
        if goal == "channel":
            results.add(ch)
        elif goal == "committed_count":
            results.add(cnt)
        elif goal == "committed_sum":
            results.add(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Family: put in {ignore, replace, upsert}, channel in {changes, total_main, total_both}, trigger in {none, after-insert}. Simulate SQLite semantics including transactions and trigger effects on total_changes.", "lesson": "Receipts constrain the family; only predict when all consistent members agree. Trigger adds to total_changes but not changes(). REPLACE fires trigger; IGNORE does not on conflict; upsert fires only on insert."}
